open(ENGINE_ROOT + '/engine/models.py', 'w').write('"""Data structures. Time is "days from today" (day 0 = BASE_DATE) so negotiations are deterministic."""\nfrom __future__ import annotations\n\nimport datetime as dt\nfrom dataclasses import dataclass, field\nfrom typing import Optional\n\nBASE_DATE = dt.date(2026, 11, 9)\n\n\ndef day_to_date(day: int) -> str:\n    return (BASE_DATE + dt.timedelta(days=day)).strftime("%b %d")\n\n\n@dataclass\nclass Column:\n    name: str\n    dtype: str\n    deprecated_until: Optional[int] = None  # day number; None = active\n    replaced_by: Optional[str] = None\n\n\n@dataclass\nclass Contract:\n    table: str\n    version: int\n    columns: dict  # name -> Column\n    notes: list = field(default_factory=list)\n\n\n@dataclass\nclass Change:\n    kind: str  # rename_column | drop_column | change_type | change_meaning\n    column: str\n    effective_day: int\n    new_name: Optional[str] = None\n    new_dtype: Optional[str] = None\n    factor: Optional[float] = None  # change_meaning: values are multiplied by this\n\n    def describe(self) -> str:\n        if self.kind == "rename_column":\n            return f"rename `{self.column}` to `{self.new_name}`"\n        if self.kind == "drop_column":\n            return f"drop `{self.column}`"\n        if self.kind == "change_type":\n            return f"change the type of `{self.column}` to {self.new_dtype}"\n        return f"change the meaning of `{self.column}` (values now multiplied by {self.factor:g})"\n\n\n@dataclass\nclass Proposal:\n    change: Change\n    effective_day: int\n    overlap_days: int = 0  # how long the old column stays next to the new one\n    compat_view: bool = False  # a view that keeps the old shape alive\n    view_days: int = 0\n    snapshot: bool = False  # frozen snapshot export of the old column\n\n    def key(self):\n        return (self.effective_day, self.overlap_days, self.compat_view, self.view_days, self.snapshot)\n\n\n@dataclass\nclass Producer:\n    name: str\n    max_overlap_days: int  # longest it will keep two copies of a column\n    max_view_days: int  # longest it will keep a compatibility view\n    latest_day: int  # release deadline\n\n\n@dataclass\nclass Consumer:\n    name: str\n    kind: str  # dashboard | ml_model | report | stream_job\n    owner: str\n    notice_days: int = 0\n    min_overlap_days: int = 0\n    freeze: Optional[tuple] = None  # (start_day, end_day) blackout window\n    can_use_view: bool = False\n    can_use_snapshot: bool = False\n    hard_dependency: set = field(default_factory=set)  # columns it cannot replace\n\n\n@dataclass\nclass Response:\n    consumer: str\n    accept: bool\n    issues: list  # each: {type, ask, text}\n\n\n@dataclass\nclass Message:\n    round: int\n    speaker: str\n    role: str  # producer | consumer | system\n    kind: str  # propose | object | counter | accept | escalate | info\n    text: str\n\n\n@dataclass\nclass Agreement:\n    change: Change\n    effective_day: int\n    overlap_days: int\n    compat_view: bool\n    view_days: int\n    snapshot: bool\n    signed_by: list\n    new_contract: Contract\n\n\n@dataclass\nclass Result:\n    status: str  # agreed | escalated\n    messages: list\n    rounds: list  # per round: {round, proposal, responses}\n    affected: list\n    unaffected: list\n    agreement: Optional[Agreement] = None\n    open_issues: list = field(default_factory=list)\n')

# COMMAND ----------

open(ENGINE_ROOT + '/engine/backend.py', 'w').write('"""Thin SQL backends. The same pipeline runs on DuckDB (local tests) and Spark (Databricks)."""\nfrom __future__ import annotations\n\nimport re\n\n_NUMERIC = re.compile(r"^(u?(tiny|small|big|huge)?int(eger)?|long|float|double|decimal|numeric|real)\\b")\n\n\ndef category(sql_type: str) -> str:\n    """numeric | string | temporal | bool | other"""\n    t = sql_type.lower().strip()\n    if re.match(r"^(struct|array|map|row|union|variant|binary|blob|interval|object)\\b", t) or "<" in t or t.endswith("[]"):\n        return "other"\n    if t.startswith("bool"):\n        return "bool"\n    if "timestamp" in t or t.startswith("date"):\n        return "temporal"\n    if any(k in t for k in ("char", "string", "text")):\n        return "string"\n    if _NUMERIC.match(t):\n        return "numeric"\n    return "other"\n\n\nclass DuckBackend:\n    def __init__(self, conn):\n        self.con = conn\n\n    def run(self, sql: str) -> list:\n        return self.con.execute(sql).fetchall()\n\n    def exec(self, sql: str) -> None:\n        self.con.execute(sql)\n\n    def columns(self, table: str) -> list:\n        return [(r[0], r[1]) for r in self.con.execute(f"DESCRIBE {table}").fetchall()]\n\n\nclass SparkBackend:\n    def __init__(self, spark):\n        self.spark = spark\n\n    def run(self, sql: str) -> list:\n        return [tuple(r) for r in self.spark.sql(sql).collect()]\n\n    def exec(self, sql: str) -> None:\n        self.spark.sql(sql)\n\n    def columns(self, table: str) -> list:\n        return [(f.name, f.dataType.simpleString()) for f in self.spark.table(table).schema.fields]\n')

# COMMAND ----------

open(ENGINE_ROOT + '/engine/llm.py', 'w').write('"""LLM layer. The model writes each team\'s lines and proposes the producer\'s counter-offers.\n\nIt never decides whether a deal is valid: the rule engine is the referee. Every model output is\nvalidated (JSON shape, limits, numbers kept intact) and falls back to the rule-based text or offer.\n"""\nfrom __future__ import annotations\n\nimport json\nimport re\n\nfrom .models import Proposal\n\n\ndef spark_ask(spark, endpoint: str, max_retries: int = 1):\n    """Return ask(prompt) -> str that calls a Databricks model endpoint through ai_query."""\n    def ask(prompt: str) -> str:\n        safe = prompt.replace("\\\\", "\\\\\\\\").replace("\'", "\\\\\'")\n        for attempt in range(max_retries + 1):\n            try:\n                return spark.sql(f"SELECT ai_query(\'{endpoint}\', \'{safe}\') AS r").collect()[0]["r"]\n            except Exception:  # noqa: BLE001\n                if attempt == max_retries:\n                    raise\n    return ask\n\n\ndef _json(text: str):\n    m = re.search(r"\\{.*\\}", text or "", re.S)\n    try:\n        return json.loads(m.group(0)) if m else None\n    except Exception:  # noqa: BLE001\n        return None\n\n\ndef _numbers(s: str) -> set:\n    return set(re.findall(r"\\d+", s))\n\n\nclass LLM:\n    def __init__(self, ask):\n        self.ask = ask\n        self.log = []  # (purpose, prompt, reply) for tracing\n\n    def _call(self, purpose: str, prompt: str):\n        try:\n            reply = self.ask(prompt)\n        except Exception as e:  # noqa: BLE001\n            reply = f"ERROR: {e}"\n        self.log.append((purpose, prompt, reply))\n        return reply\n\n    def voices(self, context: str, items: list) -> dict:\n        """items: [{name, role, facts, draft}] -> {name: line}. Lines that lose a number are dropped."""\n        prompt = (\n            f"You write lines in a negotiation about a database change: {context}\\n"\n            "For each participant write one or two short sentences in the first person, in their voice. Say what "\n            "their \'draft\' says and add a reason taken from their \'facts\'. Never change, drop or invent numbers or "\n            "dates: every number in the draft must appear in your line. Reply with ONLY a JSON object that maps "\n            f"each participant\'s name to their line.\\nParticipants: {json.dumps(items)}")\n        data = _json(self._call("voices", prompt)) or {}\n        out = {}\n        for it in items:\n            line = data.get(it["name"])\n            if isinstance(line, str) and line.strip() and _numbers(it["draft"]) <= _numbers(line):\n                out[it["name"]] = line.strip()\n        return out\n\n    def counter(self, producer, proposal: Proposal, objections: list, today: int):\n        """Ask the model for the producer\'s next offer. Returns (Proposal, message) or None if invalid."""\n        prompt = (\n            f"You are the {producer.name} negotiating a database change. Current offer: effective day "\n            f"{proposal.effective_day}, old column kept {proposal.overlap_days} days, compatibility view "\n            f"{proposal.compat_view}, snapshot {proposal.snapshot}. Objections: {json.dumps(objections)}.\\n"\n            f"You may change ONLY: effective_day (integer days from today, at most {producer.latest_day}), "\n            f"overlap_days (0 to {producer.max_overlap_days}), compat_view (true/false; it lasts "\n            f"{producer.max_view_days} days), snapshot (true/false). Make the SMALLEST concession that answers the "\n            "objections. Reply with ONLY JSON: "\n            \'{"effective_day": int, "overlap_days": int, "compat_view": bool, "snapshot": bool, \'\n            \'"message": "one sentence explaining the offer that mentions each number"}\')\n        d = _json(self._call("counter", prompt))\n        try:\n            day, overlap = int(d["effective_day"]), int(d["overlap_days"])\n            view, snap, msg = bool(d["compat_view"]), bool(d["snapshot"]), str(d["message"]).strip()\n        except Exception:  # noqa: BLE001\n            return None\n        if not (today <= day <= producer.latest_day and 0 <= overlap <= producer.max_overlap_days and msg):\n            return None\n        new = Proposal(change=proposal.change, effective_day=day, overlap_days=overlap, compat_view=view,\n                       view_days=producer.max_view_days if view else 0, snapshot=snap)\n        return None if new.key() == proposal.key() else (new, msg)\n')

# COMMAND ----------

open(ENGINE_ROOT + '/engine/serialize.py', 'w').write('"""Turn a negotiation Result into plain JSON and back, so it can be computed on Databricks and shown in the app."""\nfrom __future__ import annotations\n\nfrom dataclasses import asdict\n\nfrom .models import Agreement, Change, Column, Contract, Message, Proposal, Response, Result\n\n\ndef result_to_dict(res: Result) -> dict:\n    a = res.agreement\n    return {\n        "status": res.status, "affected": res.affected, "unaffected": res.unaffected, "open_issues": res.open_issues,\n        "messages": [asdict(m) for m in res.messages],\n        "rounds": [{"round": r["round"], "proposal": asdict(r["proposal"]),\n                    "responses": [{"consumer": x.consumer, "accept": x.accept} for x in r["responses"]]}\n                   for r in res.rounds],\n        "agreement": None if a is None else {**asdict(a)},\n    }\n\n\ndef _change(d):\n    return Change(**d)\n\n\ndef result_from_dict(d: dict) -> Result:\n    rounds = [{"round": r["round"], "proposal": Proposal(**{**r["proposal"], "change": _change(r["proposal"]["change"])}),\n               "responses": [Response(x["consumer"], x["accept"], []) for x in r["responses"]]} for r in d["rounds"]]\n    agreement = None\n    if d["agreement"]:\n        a = d["agreement"]\n        c = a["new_contract"]\n        contract = Contract(c["table"], c["version"], {n: Column(**col) for n, col in c["columns"].items()}, c["notes"])\n        agreement = Agreement(change=_change(a["change"]), effective_day=a["effective_day"],\n                              overlap_days=a["overlap_days"], compat_view=a["compat_view"], view_days=a["view_days"],\n                              snapshot=a["snapshot"], signed_by=a["signed_by"], new_contract=contract)\n    return Result(d["status"], [Message(**m) for m in d["messages"]], rounds, d["affected"], d["unaffected"],\n                  agreement, d["open_issues"])\n')

# COMMAND ----------

open(ENGINE_ROOT + '/engine/workload.py', 'w').write('"""Generate a workload of downstream reports from the SCHEMA alone (no hand-picked consumers).\n\nReal organisations already have consumers. We have none, so this builds a deterministic set of\ndashboards, features, reports and monitors over whatever tables exist, including reports built on\nother reports. Everything about a consumer except its SQL (kind, owner, refresh cadence) is\nassigned by template and is stored as data, not code.\n"""\nfrom __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass\n\nfrom .backend import category\n\nSAFE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")\nKIND_META = {  # template role -> (owner team, refresh cadence in hours)\n    "dashboard": ("BI team", 24), "ml_model": ("Data science", 168),\n    "report": ("Finance and operations", 168), "stream_job": ("Risk", 1)}\nTEXTY = ("email", "name", "text", "message", "description", "url", "comment", "log", "address", "phone")\n\n\n@dataclass\nclass Spec:\n    name: str\n    sql: str\n    kind: str\n    owner: str\n    cadence_hours: int\n    level: int\n    outputs: tuple = ()  # output column names (used to build level-2 reports)\n\n\ndef _singular(t: str) -> str:\n    return t[:-3] + "y" if t.endswith("ies") else t[:-1] if t.endswith("s") else t\n\n\ndef _spec(name, sql, kind, level=1, outputs=()):\n    owner, cadence = KIND_META[kind]\n    return Spec(name, sql, kind, owner, cadence, level, tuple(outputs))\n\n\ndef _roles(cols):\n    cols = [(n, t) for n, t in cols if SAFE.match(n)]\n    ids = [n for n, _ in cols if n == "id" or n.endswith("_id")]\n    nums = [n for n, t in cols if category(t) == "numeric" and n not in ids]\n    times = [n for n, t in cols if category(t) == "temporal"]\n    cats = [n for n, t in cols if category(t) == "string" and n not in ids\n            and not any(k in n for k in TEXTY)]\n    return ids, nums, times, cats\n\n\ndef _candidates(table, cols):\n    ids, nums, times, cats = _roles(cols)\n    out = []\n    for cat in cats[:2]:\n        extra = f", SUM({nums[0]}) AS total_{nums[0]}" if nums else ""\n        out.append(_spec(f"agg_{table}_by_{cat}",\n                         f"SELECT {cat}, COUNT(*) AS n{extra} FROM {table} GROUP BY {cat} ORDER BY {cat} LIMIT 200",\n                         "dashboard", outputs=[cat, "n"]))\n    if times and nums:\n        out.append(_spec(f"trend_{table}_{nums[0]}",\n                         f"SELECT substr(CAST({times[0]} AS STRING),1,7) AS month, SUM({nums[0]}) AS total "\n                         f"FROM {table} GROUP BY 1 ORDER BY 1", "dashboard"))\n    for fk in [i for i in ids if i != "id"][:2]:\n        parts = [f"{fk}", "COUNT(*) AS n"]\n        if nums:\n            parts.append(f"AVG({nums[0]}) AS avg_{nums[0]}")\n        if times:\n            parts.append(f"MAX(CAST({times[0]} AS STRING)) AS last_seen")\n        out.append(_spec(f"features_{table}_by_{fk}",\n                         f"SELECT {\', \'.join(parts)} FROM {table} GROUP BY {fk} ORDER BY {fk} LIMIT 200", "ml_model"))\n    latest = f"MAX(CAST({times[0]} AS STRING))" if times else (f"MAX({nums[0]})" if nums else "COUNT(*)")\n    out.append(_spec(f"latest_{table}", f"SELECT COUNT(*) AS n, {latest} AS latest FROM {table}", "stream_job"))\n    return out\n\n\ndef _joins(tables):\n    out = []\n    for a, acols in tables.items():\n        a_ids, a_nums, _, _ = _roles(acols)\n        if not a_nums:\n            continue\n        for fk in [i for i in a_ids if i != "id"]:\n            for b, bcols in tables.items():\n                if b == a or fk != _singular(b) + "_id":\n                    continue\n                b_ids, _, _, b_cats = _roles(bcols)\n                pk = fk if fk in b_ids else "id" if "id" in b_ids else None\n                if pk and b_cats:\n                    out.append(_spec(\n                        f"join_{a}_{b}",\n                        f"SELECT {b}.{b_cats[0]} AS {b_cats[0]}, COUNT(*) AS n, SUM({a}.{a_nums[0]}) AS total "\n                        f"FROM {a} JOIN {b} ON {a}.{fk} = {b}.{pk} GROUP BY {b}.{b_cats[0]} "\n                        f"ORDER BY {b}.{b_cats[0]} LIMIT 200", "report"))\n    return out\n\n\ndef generate(tables: dict, max_consumers: int = 30) -> list:\n    """tables: name -> [(column, type)]. Returns specs, level-1 first, round-robin across tables."""\n    per_table = [_candidates(t, c) for t, c in tables.items()]\n    picked, i = [], 0\n    pool = [s for lst in per_table for s in lst]  # for stable ordering of joins after\n    while len(picked) < max_consumers * 3 // 4 and any(per_table):\n        lst = per_table[i % len(per_table)]\n        if lst:\n            picked.append(lst.pop(0))\n        i += 1\n    picked += _joins(tables)[: max(1, max_consumers // 6)]\n    level1 = picked[:max_consumers]\n    level2 = []\n    for s in level1:\n        if len(level1) + len(level2) >= max_consumers + max_consumers // 5:\n            break\n        if s.level == 1 and s.kind == "dashboard" and len(s.outputs) >= 2:\n            level2.append(_spec(f"top_{s.name}", f"SELECT {s.outputs[0]}, n FROM {s.name} ORDER BY n DESC LIMIT 10",\n                                "report", level=2, outputs=s.outputs[:1] + ("n",)))\n    return level1 + level2[: max(1, max_consumers // 5)]\n')

# COMMAND ----------

open(ENGINE_ROOT + '/engine/measure.py', 'w').write('"""Measure the real blast radius of every possible change by running the consumers\' own SQL.\n\nSandbox layout: each base table T is a VIEW over a physical copy T__orig. To test a change we\nredefine the view T (metadata only, cheap), re-run every consumer that depends on T, and compare\nwith the baseline. Chains of reports are handled for free because they are real views.\n"""\nfrom __future__ import annotations\n\nimport re\nfrom decimal import Decimal\n\nfrom .backend import category\n\nTARGET_TYPES = {"numeric": ["string", "bigint", "double"], "string": ["bigint", "double"],\n                "temporal": ["string"], "bool": ["string", "bigint"], "other": []}\n\n\n# ------------------------------------------------------------------- sandbox\ndef _select(cols, kind=None, column=None, param=None, compat=False):\n    out = []\n    for name, _ in cols:\n        if name != column:\n            out.append(name)\n        elif kind == "drop":\n            continue\n        elif kind == "rename":\n            out += ([name] if compat else []) + [f"{name} AS {param}"]\n        elif kind == "retype":\n            expr = f"TRY_CAST({name} AS {param})"\n            out += [name, f"{expr} AS {name}__new"] if compat else [f"{expr} AS {name}"]\n        elif kind == "meaning":\n            expr = f"{name} * {param}"\n            out += [name, f"{expr} AS {name}__v2"] if compat else [f"{expr} AS {name}"]\n    return ", ".join(out)\n\n\ndef _set_view(backend, table, cols, **variant):\n    backend.exec(f"CREATE OR REPLACE VIEW {table} AS SELECT {_select(cols, **variant)} FROM {table}__orig")\n\n\ndef build_sandbox(backend, tables: dict, specs: list) -> None:\n    """Expects physical tables `<T>__orig`. Creates view T and every consumer view."""\n    for t, cols in tables.items():\n        _set_view(backend, t, cols)\n    for s in sorted(specs, key=lambda s: s.level):\n        backend.exec(f"CREATE OR REPLACE VIEW {s.name} AS {s.sql}")\n\n\n# ------------------------------------------------------------- dependencies\ndef dependencies(specs: list, tables: dict) -> dict:\n    """name -> {base_tables (transitive), depth (longest chain of reports built on it)}"""\n    names = set(tables) | {s.name for s in specs}\n    direct = {s.name: {n for n in names if n != s.name and re.search(rf"\\b{re.escape(n)}\\b", s.sql)}\n              for s in specs}\n\n    def base(n, seen=()):\n        if n in tables:\n            return {n}\n        return set().union(*[base(d, seen + (n,)) for d in direct.get(n, ()) if d not in seen] or [set()])\n\n    def depth(n):\n        kids = [s.name for s in specs if n in direct[s.name]]\n        return 0 if not kids else 1 + max(depth(k) for k in kids)\n\n    return {s.name: {"base_tables": sorted(base(s.name)), "reads": sorted(direct[s.name]),\n                     "depth": depth(s.name)} for s in specs}\n\n\n# ---------------------------------------------------------------- comparison\ndef _norm_value(v):\n    if isinstance(v, (float, Decimal)):\n        return round(float(v), 4)\n    return None if v is None else str(v)\n\n\ndef _snapshot(rows) -> list:\n    return sorted((tuple(_norm_value(v) for v in r) for r in rows), key=lambda r: tuple(map(str, r)))\n\n\ndef _run_consumers(backend, names: list, baseline: dict) -> dict:\n    out = {}\n    for n in names:\n        try:\n            same = _snapshot(backend.run(f"SELECT * FROM {n}")) == baseline[n]\n            out[n] = ("ok", "same results as before") if same else \\\n                ("silent", "runs, but silently returns different numbers")\n        except Exception as e:  # noqa: BLE001 - the raw failure is the evidence\n            out[n] = ("error", str(e).strip().split("\\n")[0][:160])\n    return out\n\n\ndef canary(backend, tables: dict, specs: list):\n    """Sanity check that the sandbox really reacts to a change: drop a column a consumer reads and\n    confirm that consumer fails. Returns (consumer, table, column, broke) or None."""\n    deps = dependencies(specs, tables)\n    for s in specs:\n        for t in deps[s.name]["base_tables"]:\n            for col, _ in tables[t]:\n                if re.search(rf"\\b{re.escape(col)}\\b", s.sql):\n                    _set_view(backend, t, tables[t], kind="drop", column=col, param="", compat=False)\n                    try:\n                        backend.run(f"SELECT * FROM {s.name}")\n                        broke = False\n                    except Exception:  # noqa: BLE001\n                        broke = True\n                    finally:\n                        _set_view(backend, t, tables[t])\n                    return s.name, t, col, broke\n    return None\n\n\n# ------------------------------------------------------------------ measure\ndef measure(backend, tables: dict, specs: list, factor: float = 100.0, progress=print) -> dict:\n    """Returns {"rows": [...], "unread": [[table, column], ...], "deps": {...}}."""\n    deps = dependencies(specs, tables)\n    baseline = {s.name: _snapshot(backend.run(f"SELECT * FROM {s.name}")) for s in specs}\n    rows, unread = [], []\n\n    def trial(table, cols, kind, column, param, compat, only=None):\n        names = only or [n for n, d in deps.items() if table in d["base_tables"]]\n        try:\n            _set_view(backend, table, cols, kind=kind, column=column, param=param, compat=compat)\n        except Exception as e:  # noqa: BLE001 - this change is not expressible on this column: skip it\n            progress(f"  skipped {table}.{column} {kind} {param}: {str(e).strip().splitlines()[0][:100]}")\n            _set_view(backend, table, cols)\n            return None\n        try:\n            return _run_consumers(backend, names, baseline)\n        finally:\n            _set_view(backend, table, cols)  # always restore\n\n    def record(table, column, kind, param, mode, results):\n        for consumer, (outcome, detail) in results.items():\n            rows.append({"table": table, "column": column, "kind": kind, "param": param, "mode": mode,\n                         "consumer": consumer, "outcome": outcome, "detail": detail})\n\n    for table, cols in tables.items():\n        progress(f"measuring {table} ({len(cols)} columns)")\n        for column, typ in cols:\n            res = trial(table, cols, "drop", column, "", False)\n            if res is None or all(o == "ok" for o, _ in res.values()):\n                unread.append([table, column])\n                continue\n            record(table, column, "drop", "", "no_contract", res)\n            variants = [("rename", f"{column}_renamed")]\n            variants += [("retype", t) for t in TARGET_TYPES[category(typ)]]\n            if category(typ) == "numeric":\n                variants.append(("meaning", f"{factor:g}"))\n            for kind, param in variants:\n                res = trial(table, cols, kind, column, param, False)\n                if res is None:\n                    continue\n                record(table, column, kind, param, "no_contract", res)\n                hit = [n for n, (o, _) in res.items() if o != "ok"]\n                if hit:  # does the "keep the old shape next to the new one" plan really work?\n                    wc = trial(table, cols, kind, column, param, True, only=hit)\n                    if wc is not None:\n                        record(table, column, kind, param, "with_contract", wc)\n    return {"rows": rows, "unread": unread, "deps": deps}\n\n\ndef build_snapshot(source: str, tables: dict, specs: list, result: dict, sample_rows: int,\n                   uc_lineage=None) -> dict:\n    return {\n        "source": source, "sample_rows": sample_rows,\n        "tables": {t: [list(c) for c in cols] for t, cols in tables.items()},\n        "consumers": [{"name": s.name, "kind": s.kind, "owner": s.owner, "cadence_hours": s.cadence_hours,\n                       "level": s.level, "sql": s.sql, **result["deps"][s.name]} for s in specs],\n        "impact": result["rows"], "unread": result["unread"], "uc_lineage": uc_lineage or [],\n    }\n')

